    domains: z.array(domainSummarySchema).length(4),
  })
  .superRefine(({ domains }, context) => {
    const uniqueDomains = new Set(domains.map(({ domain }) => domain))
    if (uniqueDomains.size !== domains.length) {
      context.addIssue({
        code: 'custom',
        path: ['domains'],
        message: 'domains must contain each domain exactly once',
      })
    }
  })

dueCountResponseSchema = z.object({
  dueCount: z.number().int().nonnegative(),
})

function isValidCalendarDate(value: string): boolean {
  const match = isoCalendarDatePattern.exec(value)
  if (!match) return false

  const year = Number(match[1])
  const month = Number(match[2])
  const day = Number(match[3])
  const isLeapYear = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0)
  const daysInMonth = [31, isLeapYear ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1]

  return month >= 1 && month <= 12 && day >= 1 && day <= (daysInMonth ?? 0)
}

lessonViewRequestSchema = z
  .object({
    lessonId: z.string().min(1),
  })
  .strict()

lessonViewResponseSchema = z.object({
  recorded: z.literal(true),
})

mistakeItemSchema = z
  .object({
    questionId: z.string().min(1),
    incorrectRate: z.number().min(0).max(100),
    answerCount: z.number().int().min(2),
    incorrectAnswerCount: z.number().int().nonnegative(),
  })
  .superRefine(({ answerCount, incorrectAnswerCount, incorrectRate }, context) => {
    if (incorrectRate !== Math.round((incorrectAnswerCount / answerCount) * 1000) / 10) {
      context.addIssue({
        code: 'custom',
        path: ['incorrectRate'],
        message: 'incorrectRate must match the counts rounded to one decimal place',
      })
    }
    if (incorrectAnswerCount > answerCount) {
      context.addIssue({
        code: 'custom',
        path: ['incorrectAnswerCount'],
        message: 'incorrectAnswerCount must not exceed answerCount',
      })
    }
  })

mistakesResponseSchema = z
  .object({
    items: z.array(mistakeItemSchema).max(10),
  })
  .superRefine(({ items }, context) => {
    items.forEach((item, index) => {
      const previous = items[index - 1]
      if (previous && compareMistakeRank(previous, item) > 0) {
        context.addIssue({
          code: 'custom',
          path: ['items', index],
          message: 'items must follow mistake ranking order',
        })
      }
    })
  })

rateLimitedErrorResponseSchema = z.object({
  error: z.object({
    code: z.literal('RATE_LIMITED'),
    message: z.literal('Too Many Requests'),
  }),
})

rateLimitUnavailableErrorResponseSchema = z.object({
  error: z.object({
    code: z.literal('RATE_LIMIT_UNAVAILABLE'),
    message: z.literal('Rate limit unavailable'),
  }),
})

recentActivityBaseSchema = z.object({
  id: z.string().min(1),
  occurredAt: z.number().int().nonnegative(),
})

recentActivityLessonViewedSchema = recentActivityBaseSchema
  .extend({
    type: z.literal('lesson_viewed'),
    lessonId: z.string().min(1),
  })
  .strict()

recentActivityResponseSchema = z
  .object({
    items: z.array(recentActivityItemSchema).max(10),
  })
  .superRefine(({ items }, context) => {
    const uniqueIds = new Set(items.map(({ id }) => id))
    if (uniqueIds.size !== items.length) {
      context.addIssue({
        code: 'custom',
        path: ['items'],
        message: 'items must contain unique IDs',
      })
    }

    items.forEach((item, index) => {
      const previous = items[index - 1]
      if (previous && compareRecentActivity(previous, item) > 0) {
        context.addIssue({
          code: 'custom',
          path: ['items', index],
          message: 'items must follow occurredAt descending and ID ascending order',
        })
      }
    })
  })

retentionDistributionSchema = z.object({
  masteredCount: z.number().int().nonnegative(),
  learningCount: z.number().int().nonnegative(),
  dueCount: z.number().int().nonnegative(),
})

reviewQueueResponseSchema = z.object({
  hasMore: z.boolean(),
  items: z
    .array(
      z.object({
        questionId: z.string().min(1),
        // Unix epoch milliseconds（SRS の dueAt と同じ表現）。
        dueAt: z.number().int().nonnegative(),
      }),
    )
    .max(20),
})

DOMAIN_LABELS: Record<DomainKey, { label: string; order: number }> = {
  security: { label: 'セキュリティ', order: 1 },
  frontend: { label: 'フロントエンド', order: 2 },
  backend: { label: 'バックエンド', order: 3 },
  architecture: { label: 'アーキテクチャ', order: 4 },
}

topicFrontmatterSchema = z.object({
  topic: z.string().min(1),
  title: z.string().min(1),
  order: z.number().int().nonnegative(),
})

validatedLessonFrontmatterSchema = lessonFrontmatterSchema.superRefine(
  (lesson, ctx) => {
    const questionIdPattern = new RegExp(`^${lesson.lessonId}-q\\d+$`)

    for (const [i, question] of lesson.questions.entries()) {
      if (!questionIdPattern.test(question.id)) {
        ctx.addIssue({
          code: z.ZodIssueCode.custom,
          message: `questionId must match pattern ${lesson.lessonId}-q<number>`,
          path: ['questions', i, 'id'],
        })
      }
    }
  },
)

validatedMcqSchema = mcqQuestionSchema.refine(
  (q) => q.answerIndex < q.choices.length,
  {
    message: 'answerIndex must point to an existing choice',
    path: ['answerIndex'],
  },
)

export function initialSrs(): SrsInput {
  return { ease: INITIAL_EASE, intervalDays: 0, reps: 0, lapses: 0 }
}

export function isDue(dueAt: number, now: number): boolean {
  return dueAt <= now
}

export function reviewSrs(state: SrsInput, correct: boolean, now: number): SrsResult {
  if (!correct) {
    // 不正解: reps をリセットし、翌日に再出題。ease は下限まで下げる。
    const ease = Math.max(MIN_EASE, state.ease - 200)
    return {
      ease,
      intervalDays: 1,
      reps: 0,
      lapses: state.lapses + 1,
      dueAt: now + 1 * DAY_MS,
    }
  }

  const reps = state.reps + 1
  let intervalDays: number
  if (reps === 1) {
    intervalDays = 1
  } else if (reps === 2) {
    intervalDays = 6
  } else {
    intervalDays = Math.round(state.intervalDays * (state.ease / 1000))
  }

  // 正解時は ease を微増(SM-2 の grade=4 相当)。
  const ease = Math.max(MIN_EASE, state.ease + 0)

  return {
    ease,
    intervalDays,
    reps,
    lapses: state.lapses,
    dueAt: now + intervalDays * DAY_MS,
  }
}

export type SrsInput = {
  ease: number
  intervalDays: number
  reps: number
  lapses: number
}
